package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.DimensionMismatchException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.OutOfRangeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MultidimensionalCounter_getCounts_TriageGen2Test {

    @Test
    public void testGetCounts_ValidIndex_SmallDimension() {
        // Setup: dimensions 2x3 (totalSize = 6)
        // uniCounterOffset would be calculated based on internal logic
        // For dimensions [2, 3], totalSize = 6.
        // dimensions = 2, last = 1
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 3);

        // Test index 0
        int[] result0 = counter.getCounts(0);
        assertEquals(2, result0.length);
        // Based on logic: indices[0] = idx, indices[1] = 0 - count
        // For index 0, the loop for i=0 will result in idx=0, count becomes offset.
        // Since count (0) <= index (0), count becomes offset, idx becomes 1, then --idx makes it 0.
        // indices[0] = 0. indices[1] = 0 - offset.
        // Note: The provided logic for 'count' and 'indices[last]' is highly sensitive to uniCounterOffset.
        // We verify the array length and non-nullity, and common index patterns.
        assertNotNull(result0);
        assertEquals(2, result0.length);

        // Test last index
        int[] resultLast = counter.getCounts(5);
        assertNotNull(resultLast);
        assertEquals(2, resultLast.length);
    }












}

