public class MultidimensionalCounter_getCounts_TriageGen2Test {













    @Test
    public void testGetCounts_SingleDimension() {
        MultidimensionalCounter counter = new MultidimensionalCounter(10);
        int[] result = counter.getCounts(5);
        assertEquals(1, result.length);
        // For dimension 1, last = 0. 
        // The loop i < last (0 < 0) won't execute.
        // indices[0] = index - count (where count is 0).
        assertEquals(5, result[0]);
    }
